// Inspect given components and media symbols
function describe(n, depth){
  let s = "";
  const kids = n.children || [];
  s += `  `.repeat(depth) + `${n.type} "${n.name}" id=${n.id}`;
  if (n.type === 'TEXT') s += ` chars=${JSON.stringify(n.characters)} font=${n.fontName&&n.fontName.family}`;
  s += "\n";
  for (const k of kids.slice(0,8)) s += describe(k, depth+1);
  return s;
}
