  const hex=h=>{h=h.replace('#','');return {r:parseInt(h.substr(0,2),16)/255,g:parseInt(h.substr(2,2),16)/255,b:parseInt(h.substr(4,2),16)/255};};

  // ---- helpers ----
  function fr(name,x,y,w,h,fill){const f=figma.createFrame();f.name=name;f.x=x;f.y=y;f.resize(w,h);
    f.fills=fill?[{type:'SOLID',color:hex(fill)}]:[];f.clipsContent=true;return f;}
  function rect(x,y,w,h,fill,radius){const r=figma.createRectangle();r.resize(w,h);r.x=x;r.y=y;
    if(fill)r.fills=[{type:'SOLID',color:hex(fill)}];if(radius)r.cornerRadius=radius;return r;}
  function text(str,x,y,size,weight,color){const t=figma.createText();t.fontName={family:'Montserrat',style:weight};
    t.fontSize=size;t.characters=str;t.x=x;t.y=y;t.fills=[{type:'SOLID',color:hex(color)}];return t;}
  function add(p,n){p.appendChild(n);return n;}
  async function cloneById(id){const s=figma.getNodeById(id);if(!s)return null;try{return s.clone();}catch(e){return null;}}
  function colorFill(node,c){if(Array.isArray(node.fills)&&node.fills.length){try{node.fills=[{type:'SOLID',color:hex(c)}];}catch(e){}}
    (node.children||[]).forEach(ch=>colorFill(ch,c));}
  function line(p,x,y,w,h,c){add(p,rect(x,y,w,h,c));}

  // ========= create reusable components (as local components on workspace) =========
  // 1) Status bar + home indicator: clone given
