    col.fills=[]; col.clipsContent=false; col.layoutMode='VERTICAL'; col.primaryAxisAlignMode='CENTER';
    col.counterAxisAlignMode='CENTER'; col.itemSpacing=2; col.paddingTop=10; col.paddingBottom=8;
    const iconWrap=figma.createFrame(); iconWrap.resize(tw,26); iconWrap.fills=[];
    const icon=cloneById(t.iconId); if(icon){ icon.resize(22,22); iconWrap.appendChild(icon);}
    colorFill(iconWrap,'#9A9AA6');
    const label=text(t.label,0,0,10,'Medium','#9A9AA6');
    navComp.appendChild(col); col.appendChild(iconWrap); col.appendChild(label);
    tabs.push({col,iconWrap,label});
  });
  // top border
  const topLine=rect(0,0,375,1,'#EFEFF3'); navComp.appendChild(topLine);
  add(ws, navComp);

  // per-tab active helper stored? We'll create a helper accessed via global later.

  // 3) Header component (back + title + action)
  const headerComp = figma.createComponent(); headerComp.name="ScreenHeader"; headerComp.resize(375,60); headerComp.fills=[{type:'SOLID',color:hex('#FFFFFF')}];
  add(ws, headerComp);

  // 4) Product card component (image + name + desc + price + rating)
  const cardComp = figma.createComponent(); cardComp.name="ProductCard"; cardComp.resize(176,238); cardComp.fills=[];
  add(ws, cardComp);

  // ========= create the 15 empty frames =========
  const specs=[['01_Splash',0,0],['02_Onboarding_Choose_Products',400,0],['03_Onboarding_Make_Payment',800,0],
    ['04_Onboarding_Get_Your_Order',1200,0],['05_Sign_In',1600,0],['06_Sign_Up',2000,0],['07_Forgot_Password',2400,0],
    ['08_Get_Started',2800,0],['09_Home',3200,0],['10_Product_List',3600,0],['11_Product_Detail',4000,0],
    ['12_Shopping_Bag',4400,0],['13_Payment',4800,0],['14_Payment_Success_Overlay',5200,0],['15_Profile',5600,0]];
  const frames={};
  for(const [nm,x,y] of specs){ const f=fr(nm,x,y,375,812,'#FFFFFF'); add(ws,f); frames[nm]=f; }

  // store globals for later (not persisted). Emit a probe text
  const done=text("BATCH A OK components="+navComp.id+" frames="+frames['05_Sign_In'].id, 0,1500,14,'Regular','#000000'); add(ws,done);
}
