async function run(){
  const ws = figma.getNodeById("5:2"); // 03 · Workspace
  await figma.setCurrentPageAsync(ws);
  figma.currentPage = ws;

  // remove probe markers
  for (const c of [...ws.children]){ if(c.name==="PROBE_MARKER"||c.name==="PROBE2") c.remove(); }

  const BRAND = {r:0xF8/255,g:0x37/255,b:0x58/255};
  const DARK = {r:0x1D/255,g:0x1F/255,b:0x27/255};
  const MID = {r:0x55/255,g:0x58/255,b:0x63/255};
  const GRAY = {r:0x8A/255,g:0x8D/255,b:0x98/255};
  const BORDER = {r:0xE6/255,g:0xE6/255,b:0xE6/255};
  const WHITE = {r:1,g:1,b:1};
  const OFF = {r:0xF5/255,g:0xF5/255,b:0xF7/255};
  const STAR = {r:0xFF/255,g:0xB6/255,b:0x00/255};
  const GREEN = {r:0x2E/255,g:0x7D/255,b:0x32/255};

  async function loadFonts(styles){
    for(const s of styles){ await figma.loadFontAsync({family:"Montserrat", style:s}); }
  }
  await loadFonts(["Regular","Medium","SemiBold","Bold"]);

  function solid(color){ return {type:'SOLID', color: color}; }
  function rect(name,x,y,w,h,r,color){
    const n = figma.createRectangle();
    n.name=name; n.x=x; n.y=y; n.resize(w,h);
    if(r){ n.cornerRadius=r; } else { n.cornerRadius=0; }
    n.fills=[solid(color)];
    return n;
  }
  function text(txt,x,y,w,size,weight,color,align){
    const n = figma.createText();
    n.fontName={family:"Montserrat", style:weight};
    n.characters=txt;
    n.textAlignHorizontal = align||'LEFT';
    n.resize(w, size*1.4);
    n.x=x; n.y=y;
    n.textAutoResize='HEIGHT';
    n.fontSize=size;
    n.fills=[solid(color)];
    n.lineHeight={value:size*1.35, unit:'PERCENT'};
    return n;
  }

  // find & clone a source node by exact name (search all pages)
  function findNode(name,node){
    if(!node) return null;
    if(node.name===name) return node;
    if(node.children){ for(const c of node.children){ const r=findNode(name,c); if(r) return r; } }
    return null;
  }
  async function cloneMedia(name){
    let src = findNode(name, figma.root);
    if(!src) return null;
    const cl = src.clone();
    return cl;
  }

  window.__h = {BRAND,DARK,MID,GRAY,BORDER,WHITE,OFF,STAR,GREEN,solid,rect,text,cloneMedia,findNode,ws};
  return "helpers ready";
}
