async function run(){
  const ws = figma.getNodeById("5:2");
  await figma.setCurrentPageAsync(ws);

  const C = h => { let s=h.replace('#',''); return {r:parseInt(s.substr(0,2),16)/255, g:parseInt(s.substr(2,2),16)/255, b:parseInt(s.substr(4,2),16)/255}; };
  const COL = {
    brand:C('#F83758'), brandDark:C('#E02D4D'),
    ink:C('#1C1C28'), sub:C('#6B6F76'), tert:C('#9CA0A8'),
    bg:C('#FFFFFF'), bggray:C('#F5F5F7'), border:C('#E6E6EA'),
    gold:C('#FFB935'), success:C('#2EBD59'), error:C('#EB4D4B'), line:C('#EFEFF2')
  };

  function findNode(name,node){
    if(!node) return null;
    if(node.name===name) return node;
    if(node.children){ for(const c of node.children){ const r=findNode(name,c); if(r) return r; } }
    return null;
  }
  function R(parent,x,y,w,h,color,radius){
    const r=figma.createRectangle(); r.x=x; r.y=y; r.resize(w,h);
    r.fills=[{type:'SOLID',color:color}];
    if(radius) r.cornerRadius=radius;
    parent.appendChild(r); return r;
  }
  async function T(parent,chars,x,y,w,size,weight,color,align,lineH){
    const t=figma.createText();
    t.fontName={family:'Montserrat',style:weight};
    t.fontSize=size; t.characters=chars; t.x=x; t.y=y;
    t.resize(w, Math.max(size, (lineH||Math.round(size*1.4))));
    t.textAlignHorizontal=align||'LEFT';
    t.fills=[{type:'SOLID',color:color}];
    parent.appendChild(t); return t;
  }
  // mount media centered horizontally at cx, anchored top at y
  function mount(parent,name,y,h,cx){
    const src=findNode(name,figma.root); if(!src) return null;
    const cl=src.clone();
    const aspect=src.width/src.height;
    cl.resize(Math.round(h*aspect), h);
    cl.x=Math.round((cx||187.5)-cl.width/2); cl.y=y;
    parent.appendChild(cl); return cl;
  }

  // ---- Load fonts
  const fonts=[['Montserrat','Regular'],['Montserrat','Medium'],['Montserrat','SemiBold'],['Montserrat','Bold']];
  for(const f of fonts){ try{ await figma.loadFontAsync({family:f[0],style:f[1]}); }catch(e){} }

  // ---- Helpers for shell
  function statusBar(parent){ const sb=figma.getNodeById("2:34"); if(sb){ const cl=sb.clone(); cl.x=0; cl.y=0; parent.appendChild(cl);} }
  function homeInd(parent){ const hi=figma.getNodeById("2:45"); if(hi){ const cl=hi.clone(); cl.x=0; cl.y=778; parent.appendChild(cl);} }

  // ---- Reusable Main Navigation component
  function buildMainNav(idx, parent){
    const tabs=[['Home','Icon_Home'],['Wishlist','Icon_Wishlist'],['Cart','Icon_Cart'],['Search','Icon_Search'],['Settings','Icon_Settings']];
    R(parent,0,760,375,52,COL.bg);
    // top border
    R(parent,0,760,375,1,COL.line);
    const tabW=75;
    tabs.forEach((tb,i)=>{
      const cx=tabW*i+tabW/2;
      const active=(i===idx);
      // icon
      const icon=findNode(tb[1],figma.root);
      let ic;
      if(icon){ ic=icon.clone(); 
