function run() {
  const ws = figma.getNodeById("5:2");
  function dump(node, depth, maxDepth){
    if(depth>maxDepth) return node.children? "": "";
    let s="  ".repeat(depth)+node.type+' "'+node.name+'"'+(node.type==='TEXT'?(" text="+node.characters):"")+"\n";
    if(node.children){ for(const c of node.children) s+=dump(c,depth+1,maxDepth); }
    return s;
  }
  let out="";
  for(const id of ["35:2","35:3","35:4","35:5"]){
    const f=figma.getNodeById(id);
    out+="\n==="+f.name+"===\n"+dump(f,0,1);
  }
  throw new Error(out.slice(0,4000));
}
